# November 23, 2026: a spread of places across New Brunswick, from Saint John and the Kennebecasis valley to the Fundy islands,
# the Saint John River, the Miramichi, the Acadian shore and the Madawaska. Region nb, claimed with tools/choose.py --thinnest.
# Sources opened in this session: the Canadian Register of Historic Places statement for every place but two (historicplaces.ca,
# read with tools/page.py --all); Wikipedia as raw text (tools/wiki_raw.py) for Fort Howe and Partridge Island; and web search
# results that quote the City of Saint John market's own page and the Anglican dioceses' parish pages for opening times.
# Pins placed from Register points and the ArcGIS geocoder, then checked on the aerial.
from data_b import N
from data_ma import W
def L(t,u): return [t,u]
def HP(t,i): return ['Canadian Register of Historic Places: '+t,'https://www.historicplaces.ca/en/rep-reg/place-lieu.aspx?id=%d'%i]
BATCH={'key':'nb_kfxr','label':'Saint John, the Fundy islands, the river and the Miramichi, New Brunswick','added':'2026-11-23 18:36'}
PLACES=[
N('fort-howe-saint-john','Fort Howe (site and replica blockhouse)','Saint John','nb','fort','traces',45.27709,-66.07165,'site','public','walk','forts','1777–1870',
  'The British built Fort Howe in 1777, after American privateers raided the settlement at the mouth of the Saint John River, on a limestone knoll above the harbour. It began as a blockhouse and barracks inside a palisade, with a second blockhouse at the east end of the hill; after Parrtown (now Saint John) was founded in 1783 it was the military headquarters and the first jail. A fire in 1819 destroyed the barracks and by 1870 the last original works had been removed. It is a National Historic Site, but the Register says no remains of the fort survive.',
  'A hilltop park with a lookout over the harbour and the river mouth. Wikipedia says a full-size replica of one of the fort\'s blockhouses was put up in 1967 about 250 metres northeast of the original; it also lists old and replica cannons and one Second World War anti-aircraft battery on the hill. Interior of the replica not checked.',
  'A replica blockhouse and a harbour view where Saint John began.',
  'Hilltop parkland owned by the City of Saint John (Wikipedia says the city has held it since 1930). Open parkland, no fee found. Wikipedia says the Imperial Order Daughters of the Empire and the city built the replica; the Register places the fort itself in the west end of the park, where a plaque stands. Parking not checked: streets and lots lie below the hill.',
  [HP('Fort Howe',13001),W('Fort Howe')],conf='mixed',brick='?'),
N('partridge-island-saint-john','Partridge Island Quarantine Station','Saint John','nb','inst','ruins',45.23800,-66.05500,'area','view','boat','','1830–1941',
  'Partridge Island, at the mouth of Saint John harbour, was a quarantine station from 1830 until 1941 and one of two major ones in 19th-century Canada. In 1847 about 2,000 Irish immigrants fleeing the famine were held here during a typhus epidemic; the Register says 601 of them lie in a mass grave on the island. The island also held a light station and was fortified in both world wars. All the buildings were demolished in 1955 and in 1998 to 1999.',
  'From the mainland, a low island with a red-and-white concrete light tower (built 1960). The Register lists what remains on it: remnants of the doctor\'s residence (about 1872), the hospitals of 1899 to 1901, a low-water wharf and a cemetery with graves from the 1847 epidemic. Wikipedia adds memorials placed in the 1980s by the Jewish community, the Orange Lodge and others.',
  'Canada\'s Ellis Island, with a mass grave of famine Irish.',
  'The Register\'s statement for the light tower says the island is no longer accessible to the public. Look from the shore of west Saint John or the harbour; nothing in the sources opened says who owns the island now or whether landing is allowed, so no way onto it is given. The pin is the island, not a single ruin.',
  [HP('Partridge Island Quarantine Station',12721),HP('Partridge Island Light Tower',13264),W('Partridge Island (Saint John County)')],conf='mixed',brick='no'),
N('saint-john-city-market','Saint John City Market','Saint John','nb','civic','standing',45.27404,-66.05924,'exact','open','walk','','1874–1876',
  'Built in 1874 to 1876 to designs by the New Brunswick architects McKean and Fairweather, the City Market survived the Great Fire of 1877 and still does the job it was built for. It is a National Historic Site as a rare surviving 19th-century building designed as a market. The Register says its timber frame is brick-faced.',
  'A long brick building running the length of a block, with a three-and-a-half-storey Second Empire front (mansard roof, dormers, central entrance) on Charlotte Street. Inside, the market hall has exposed timber framing: twenty modified queen-post trusses under semicircular arches, on cast iron columns, with semicircular clerestory windows along the sides and a wide central aisle between the stalls.',
  'A Victorian market hall still full of stalls.',
  'City-owned market at 47 Charlotte Street, across from King Square. Free to walk in; vendors set their own hours. Parking not checked: lots lie within a few blocks (OpenStreetMap shows one on King Street East).',
  [HP('Saint John City Market',7482),W('Saint John City Market'),L('Saint John City Market: about and hours','https://www.sjcitymarket.ca/about')],brick='yes',hours='Monday to Friday 7:30 a.m. to 6 p.m., Saturday 7:30 a.m. to 5 p.m.; closed Sunday (its page; Thursday evenings may run later; check)'),
N('st-johns-stone-church-saint-john','St. John\'s (Stone) Anglican Church','Saint John','nb','worship','standing',45.27603,-66.06155,'exact','open','walk','','1823–1826',
  'An early Anglican church in Romantic Gothic Revival style, built in 1823 to 1826 to designs by John Cunningham and called the "Stone Church" because stone was unusual in a colony of wooden buildings. The chancel was added in 1872 to designs by Matthew Stead; the parish hall of 1891 is separate. It is a National Historic Site of Canada.',
  'A rectangular stone church with a low gabled roof, a central pinnacled tower over the entrance, a crenelated eave line and pointed-arch windows with tracery. The Register notes an interior with an auditory hall and galleries on three sides, a plaster ceiling and the 1872 chancel. Whether the public can go in outside services is not stated.',
  'Saint John\'s first stone church, a Gothic Revival pioneer.',
  'An active parish at 87 Carleton Street at the head of Wellington Row. The Diocese of Fredericton\'s parish page, as quoted in a web search result, gives a Sunday service at 10:30 a.m.; the page itself could not be opened, so confirm before going. Street parking not checked.',
  [HP('St. John\'s Anglican Church / Stone Church',4448),L('Anglican Diocese of Fredericton: St. John (Stone Church)','https://nb.anglican.ca/saint-john/st-john-stone-church')],brick='no',hours='Sunday service 10:30 a.m. (parish page as quoted in a search result; confirm)'),
N('trinity-church-kingston-nb','Trinity Church and Rectory, Kingston','Kingston','nb','worship','standing',45.50258,-65.97568,'exact','open','drive','','1787–1789',
  'Loyalists reached Kingston in 1784 and chose a hilltop site for an Anglican church in 1787; the church and the rectory were built by 1789. It is the oldest surviving Anglican church in New Brunswick, and the Register calls it a rare Maritime case of both church and rectory surviving from the 18th century. Gothic Revival improvements were added in the 1800s. National Historic Site of Canada since 1977.',
  'A church of the plain basilican plan, with the nave running from the entrance to the altar and, the Register says, some of its Georgian composition kept. Across Route 845 stands the two-storey Georgian rectory, with a central door and four rooms round a central hall. Interior of the church not checked beyond that.',
  'New Brunswick\'s oldest Anglican church and its 1788 rectory, facing each other across a road.',
  'An active parish of the Anglican Parish of Kingston, on Route 845 (3949 Route 845 in the parish listing). The diocese and parish pages, as quoted in a search result, give Holy Communion on Sunday at 10 a.m.; in June, July and August some Sundays are held at other churches of the parish, so check its calendar. The rectory is a separate building: look from the road.',
  [HP('Trinity Church and Rectory',12087),L('Parish of Kingston: Trinity, Kingston','https://parishofkingston.ca/pages/trinity-kingston')],brick='?',hours='Sunday 10 a.m.; some summer Sundays are at other parish churches (parish page as quoted in a search result)'),
N('kings-county-court-house-hampton','Kings County Court House','Hampton','nb','civic','standing',45.52651,-65.82682,'exact','view','walk','','1872',
  'Finished in 1872 at a cost of $14,000 to designs by the Saint John architect J. T. C. McKean, the court house also held the county offices until the late 1960s. The Register calls it typical of the solid, fireproof two-storey court houses built in the Maritimes in the late 19th century, and says it has been a court house and registry office since it opened.',
  'A two-storey Second Empire building of red brick with light brown sandstone bands, a bellcast mansard roof, a slightly projecting central tower with a carved medallion reading "King\'s County", a portico with side stairs, wooden eave brackets and polychrome pointed arches. The Register says the upstairs courtroom is dramatic in scale and well preserved; it is a working court building, so interior access is not given.',
  'A Second Empire county court house facing the town square.',
  'At 648 Main Street, overlooking the main square of Hampton, on a grassed lot set back from the street. A court and registry office: look from the street, and go in only on court or registry business. Parking not checked.',
  [HP('Kings County Court House',12896)],brick='yes'),
N('christ-church-maugerville','Christ Church (Maugerville)','Maugerville','nb','worship','standing',45.87140,-66.44630,'exact','view','drive','','1856',
  'Built in 1856 to a design by the diocesan architect Frank Wills, under Bishop John Medley, as a model of an ecclesiologically correct Gothic Revival church built in wood. The Register calls it a particularly successful wooden interpretation of that style and made it a National Historic Site of Canada in 1990.',
  'A wooden church of compact rectangular mass under a steep roof, with a prominent tower, chancel, north porch and steeple, pointed-arch openings, label mouldings and ornamental wooden corner buttresses. Interior not checked.',
  'A wooden church that set the pattern for New Brunswick Gothic Revival.',
  'A parish church of the Anglican Diocese of Fredericton. The diocese\'s listing, as quoted in a web search result, gives its Sunday service at 11 a.m. at St. John\'s in Oromocto, not at Maugerville, so treat this church as view-only unless the parish says it is open. Parking not checked.',
  [HP('Christ Church Anglican',12026),L('Anglican Diocese of Fredericton: Christ Church, Maugerville','https://nb.anglican.ca/fredericton/christ-church-maugerville')],brick='no'),
N('swallowtail-lighthouse-grand-manan','Swallowtail Lighthouse','Grand Manan','nb','light','standing',44.76428,-66.73244,'exact','open','walk','','1860',
  'First lit on 7 July 1860, it was the first lighthouse on Grand Manan, built after the wreck of the Lord Ashburton in 1857 (Wikipedia). The Register says it is believed to be the seventh-oldest octagonal wooden light tower standing in Canada, and a Recognized Federal Heritage Building. It was automated and de-staffed in 1986.',
  'An octagonal tower of heavy hewn timber with a shingled skin, tapering, with eight facets for most of its height and seven near the top, on a grassy rock reached by a narrow footbridge. A summer welcome centre, museum and gift shop are mentioned in search results for the Swallowtail Keepers Society; days and hours were not confirmed. Tower interior not checked.',
  'A Fundy lighthouse on a rock reached by a footbridge.',
  'On the north end of Grand Manan, reached by ferry from Blacks Harbour. Owner not stated in the sources opened. The grounds are described in search listings as open year round, with the museum and shop open in summer only; hours not checked. Parking not checked.',
  [HP('Swallowtail Lightstation',4735),W('Swallowtail Lighthouse')],brick='no',hours='?'),
N('head-harbour-lightstation-campobello','Head Harbour (East Quoddy) Lightstation','Wilsons Beach','nb','light','standing',44.95712,-66.90434,'site','view','walk','','1829',
  'Built in 1829, it was New Brunswick\'s second lighthouse and the Register counts it among the oldest still standing in Canada. It guarded the narrow channel between Campobello Island and Maine, in fog and rock-strewn tides. Provincial Historic Site since 2006.',
  'A tapered octagonal wooden tower, 51 feet high, clad in white shingles and clapboard with a large red cross on one side; with it the keeper\'s house (about 1840), a fog alarm building, a boathouse and a work shed on a small rocky islet. Interiors not checked; Wikipedia says paid tours are offered in summer by a preservation group, with dates not found.',
  'A white lighthouse on an islet you can only walk to at low tide.',
  'Owner not stated in the sources opened. The islet can be reached on foot only around low tide (the Register says so; search results put the window at about an hour either side of low tide). The tide returns fast and wading or swimming is dangerous: check the tide table before going and leave in good time. Park at the lot at the end of Lighthouse Road (OpenStreetMap).',
  [HP('Head Harbour Light Station',6537),W('Head Harbour Lighthouse')],th=[44.95651,-66.90407],thn='Lot at the end of Lighthouse Road (OpenStreetMap)',brick='no'),
N('marine-hospital-douglastown','Marine Hospital, Douglastown','Miramichi','nb','civic','standing',47.02222,-65.51030,'exact','view','walk','','1830–1831',
  'Built by Matthew Lamont for the Commissioners of the Port of Miramichi in 1830 to 1831, the sandstone Marine Hospital is the oldest surviving marine hospital in Canada. Until 1921 it cared for poor, sick or disabled seamen, most of them timber-trade sailors. National Historic Site of Canada since 1989.',
  'A one-storey sandstone building on high ground over the Miramichi River, with smooth ashlar walls, a low flared hipped roof, a stone chimney at the east end, a domed cupola with Grecian columns, and original multi-pane windows and wooden doors. Today it serves as a church hall and community meeting place.',
  'A seamen\'s hospital of 1830, still standing over the river.',
  'At 12 Vye Street, among houses in Douglastown. In use as a church hall and meeting place; no public hours found, so look from the street. Parking not checked.',
  [HP('Marine Hospital',11707)],brick='no'),
N('old-northumberland-courthouse-miramichi','Old Northumberland County Court House','Miramichi','nb','civic','standing',47.00403,-65.57015,'exact','view','walk','','1828–1829',
  'The 1828 to 1829 court house replaced the one destroyed in the Great Miramichi Fire of 1825. It was built by William Murray, a Scottish immigrant builder of many houses, churches and public buildings on the Miramichi. When a stone court house replaced it in 1912 to 1913, it was moved in 1914 from its original site and turned into apartments. Provincial Historic Site.',
  'A two-storey Georgian clapboard building, symmetrical, with five window bays on both floors, an ornamented central door and porch, a low hipped roof and simple rectangular mass. It stands at 285 Campbell Street; as apartments, its interior is not open.',
  'A Georgian court house that survived the Miramichi fire\'s aftermath and a move.',
  'Private housing at 285 Campbell Street: look from the public street only. Parking not checked.',
  [HP('Old Northumberland County Court House',7887)],brick='no'),
N('religious-hospitallers-cemetery-tracadie','Religious Hospitallers of St. Joseph Cemetery, Tracadie','Tracadie-Sheila','nb','burial','standing',47.51270,-64.90820,'area','view','walk','','1885–1979',
  'The Religious Hospitallers of St. Joseph came to Tracadie in 1865 to nurse lepers who had been left almost as prisoners in a former lazaretto, and then opened a school (1874) and an orphanage. Their convent cemetery, laid out in 1885, holds 60 graves: 59 sisters and Father Joseph Théberge of Neguac, who helped the area\'s orphans. The most recent burial is from 1979. It is a Local Historic Place.',
  'Fifty-eight wrought-iron crosses, the priest\'s tomb and a three-metre cross recalling the sisters\' work, near the Académie Sainte-Famille. The Register says it is reached by the Heritage Trail (Sentier du Patrimoine) from the academy. The pin is a point on Du Couvent Street from the Register; exact position not checked.',
  'Iron crosses over the nuns who nursed Tracadie\'s lepers.',
  'Reached on foot by the town\'s Heritage Trail, which starts near the Académie Sainte-Famille on Du Couvent Street. Owner and hours not found in the sources opened, so it is listed as look-only: keep to the public trail and respect it as a cemetery.',
  [HP('Religious Hospitallers of St. Joseph Cemetery',5974)],conf='mixed',brick='no'),
N('cathedral-immaculate-conception-edmundston','Cathedral of the Immaculate Conception, Edmundston','Edmundston','nb','worship','standing',47.36285,-68.33252,'exact','open','walk','','1925–1927',
  'Built from 1925 to 1927 to plans by the Quebec City architects Beaulé and Morissette, in a blend of Gothic and Romanesque styles, it became the seat of the Roman Catholic Diocese of Edmundston in 1944. Mgr W. J. Conway had it built. The Register notes its decoration by Nincheri, Bonnet, Laporte and Bourgault and 21 kinds of stone and marble from Europe, Africa and North America.',
  'Tall grey granite façades with two spires, copper-sheathed roof and spires, ten-panel front doors, a large nave and transept, ground-level stained glass from the Nincheri shops, later upper windows and a stained glass rose window. Whether visitors may go in outside Mass is not stated.',
  'A granite cathedral with a Nincheri glass interior and 21 kinds of marble.',
  'At 175 Rue de l\'Église, with the bishop\'s residence beside it. Diocesan bulletins found in a web search give Sunday Masses at 9:15 a.m. in English, 11 a.m. in French and 7:15 p.m., but they are of different years: confirm with the parish (telephone number on the diocese\'s pages). Parking not checked.',
  [HP('Cathedral of the Immaculate Conception',1271),L('Diocese of Edmundston','https://www.diocese-edmundston.ca/')],brick='no',hours='Sunday Mass about 9:15 a.m. (English), 11 a.m. (French), 7:15 p.m. (diocesan bulletins of different years; confirm)'),
]
